insert into public.articles (title, slug, excerpt, content, author_key, category, sources, reading_minutes, status, legacy_import, created_at, updated_at)
values ('Antes de registrar sua marca, entenda o que está em jogo.', 'antes-de-registrar-sua-marca', 'Nome, domínio e registro: entender as diferenças ajuda a tomar uma decisão mais consciente.', '{"version":1,"blocks":[{"type":"heading","level":2,"text":"O nome é apenas o começo"},{"type":"paragraph","text":"Escolher um nome envolve muito mais do que sonoridade. A marca identifica produtos ou serviços e concentra parte da reputação do negócio. O registro no INPI é o caminho para buscar sua proteção, conforme os limites e requisitos aplicáveis."},{"type":"heading","level":2,"text":"CNPJ, domínio e marca são coisas diferentes"},{"type":"paragraph","text":"Formalizar a empresa e reservar um endereço na internet não substituem o registro de marca. Cada instrumento tem uma finalidade. Por isso, vale analisar esses elementos em conjunto, sem presumir que um protege automaticamente o outro."},{"type":"heading","level":2,"text":"Pesquisar antes de investir"},{"type":"paragraph","text":"O INPI recomenda a busca por marcas semelhantes. A análise precisa considerar também os produtos e serviços envolvidos. Ela ajuda a reconhecer possíveis conflitos antes de investir em identidade, comunicação ou expansão."},{"type":"heading","level":2,"text":"Uma decisão com contexto"},{"type":"paragraph","text":"Leve para a primeira conversa o nome que usa ou pretende usar, uma descrição da atividade e seus planos de crescimento. A orientação da Velmont parte desse contexto para discutir riscos e caminhos. A apresentação de um pedido não representa aprovação garantida."}]}'::jsonb, 'velmont', 'MARCAS', '[{"title":"INPI — Guia básico de marcas","url":"https://www.gov.br/inpi/pt-br/servicos/marcas/guia-basico"},{"title":"INPI — Marca, nome empresarial e domínio","url":"https://www.gov.br/inpi/pt-br/plataforma-integrada-de-atendimento/marca-x-nome-empresarial-x-dominio"}]'::jsonb, 2, 'published', true, '2026-09-06T12:00:03Z', '2026-09-06T12:00:03Z')
on conflict (slug) do nothing;

insert into public.articles (title, slug, excerpt, content, author_key, category, sources, reading_minutes, status, legacy_import, created_at, updated_at)
values ('Seu software também é patrimônio. Você está cuidando dele?', 'software-tambem-e-patrimonio', 'Autoria, código e titularidade precisam fazer parte da estratégia de um negócio digital.', '{"version":1,"blocks":[{"type":"heading","level":2,"text":"Além do produto que aparece na tela"},{"type":"paragraph","text":"Um software reúne decisões, conhecimento e investimento. A proteção jurídica do programa de computador se relaciona à expressão do código. Ela não significa, por si só, exclusividade sobre toda ideia ou funcionalidade de um produto."},{"type":"heading","level":2,"text":"O papel do registro"},{"type":"paragraph","text":"Segundo o INPI, o registro de programa de computador contribui para a segurança jurídica em disputas sobre autoria ou titularidade. Entender qual versão será registrada e organizar a documentação faz parte desse cuidado."},{"type":"heading","level":2,"text":"Quem criou? Quem é titular?"},{"type":"paragraph","text":"Quando sócios, empregados, parceiros ou fornecedores participam do desenvolvimento, as relações precisam estar claras. Contratos, cessão e licenciamento merecem análise no contexto de cada projeto. A Velmont trabalha essas frentes de forma integrada à estratégia do negócio."},{"type":"heading","level":2,"text":"Um bom ponto de partida"},{"type":"paragraph","text":"Organize o histórico do projeto, identifique os participantes e reúna os contratos existentes. Essas informações ajudam a primeira conversa. A análise individual define os documentos e os próximos passos adequados."}]}'::jsonb, 'velmont', 'SOFTWARE', '[{"title":"INPI — Guia básico de programa de computador","url":"https://www.gov.br/inpi/pt-br/servicos/programas-de-computador/guia-basico"},{"title":"INPI — Perguntas frequentes sobre programas de computador","url":"https://www.gov.br/inpi/pt-br/acesso-a-informacao/perguntas-frequentes/programas-de-computador"}]'::jsonb, 2, 'published', true, '2026-09-06T12:00:02Z', '2026-09-06T12:00:02Z')
on conflict (slug) do nothing;

insert into public.articles (title, slug, excerpt, content, author_key, category, sources, reading_minutes, status, legacy_import, created_at, updated_at)
values ('Da inovação à proteção: o que analisar antes de uma patente.', 'inovacao-e-patente', 'Uma criação promissora precisa ser avaliada com critérios técnicos e visão estratégica.', '{"version":1,"blocks":[{"type":"heading","level":2,"text":"Qual problema sua criação resolve?"},{"type":"paragraph","text":"A primeira conversa começa pela solução técnica e pelo contexto do negócio. Descrever o problema, o funcionamento e o que sua criação traz de diferente ajuda a organizar a análise. Não é necessário começar com uma promessa de patente."},{"type":"heading","level":2,"text":"O que já existe importa"},{"type":"paragraph","text":"A busca de anterioridade reúne informações sobre tecnologias existentes. Para uma patente de invenção, os requisitos incluem novidade, atividade inventiva e aplicação industrial. A pesquisa e a avaliação técnica ajudam a compreender o cenário, sem antecipar a decisão do INPI."},{"type":"heading","level":2,"text":"Nem todo ativo segue o mesmo caminho"},{"type":"paragraph","text":"Patente de invenção, modelo de utilidade e desenho industrial têm objetos e requisitos distintos. Identificar o que se pretende proteger é essencial para discutir a alternativa adequada. A aparência de um produto e sua solução técnica podem exigir análises diferentes."},{"type":"heading","level":2,"text":"Converse antes de definir a estratégia"},{"type":"paragraph","text":"Reúna descrições, desenhos e o histórico de desenvolvimento. Na conversa inicial, evite enviar informações técnicas confidenciais até alinhar com a equipe a forma adequada de compartilhamento. O objetivo é entender o projeto e organizar uma análise responsável."}]}'::jsonb, 'velmont', 'PATENTES', '[{"title":"INPI — Guia básico de patentes","url":"https://www.gov.br/inpi/pt-br/servicos/patentes/guia-basico/guia-basico/"},{"title":"INPI — Serviços de propriedade industrial","url":"https://www.gov.br/inpi/pt-br/servicos"}]'::jsonb, 2, 'published', true, '2026-09-06T12:00:01Z', '2026-09-06T12:00:01Z')
on conflict (slug) do nothing;

insert into public.published_articles (article_id, slug, title, excerpt, content, category, tags, author_key, sources, robots_index, reading_minutes, created_at, source_version)
select a.id, a.slug, a.title, a.excerpt, a.content, a.category, a.tags, a.author_key, a.sources, a.robots_index, a.reading_minutes, a.created_at, a.version
from public.articles a
where a.legacy_import and a.status = 'published'
on conflict (article_id) do nothing;
